package io.github.finalparadox.item;
import com.google.common.collect.*;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.Enchantments;import net.minecraft.world.level.Level;import java.util.*;
public final class ThornKnightAegisItem extends ArmorItem{
 private final Multimap<Attribute,AttributeModifier> mods;public ThornKnightAegisItem(){super(ArmorMaterials.DIAMOND,Type.CHESTPLATE,new Properties().stacksTo(1));ImmutableMultimap.Builder<Attribute,AttributeModifier>b=ImmutableMultimap.builder();b.putAll(super.getDefaultAttributeModifiers(EquipmentSlot.CHEST));b.put(Attributes.MAX_HEALTH,new AttributeModifier(UUID.fromString("bac647d6-0a0a-44ba-b97e-0c7b663d632b"),"Thorn aegis health",2,AttributeModifier.Operation.ADDITION));mods=b.build();}
 @Override public ItemStack getDefaultInstance(){ItemStack s=super.getDefaultInstance();prepare(s);return s;}@Override public void inventoryTick(ItemStack s,Level l,Entity e,int slot,boolean selected){prepare(s);super.inventoryTick(s,l,e,slot,selected);}private static void prepare(ItemStack s){s.getOrCreateTag().putBoolean("Unbreakable",true);s.getOrCreateTag().putInt("HideFlags",4);if(s.getEnchantmentLevel(Enchantments.ALL_DAMAGE_PROTECTION)<4)s.enchant(Enchantments.ALL_DAMAGE_PROTECTION,4);if(s.getEnchantmentLevel(Enchantments.THORNS)<4)s.enchant(Enchantments.THORNS,4);if(s.getEnchantmentLevel(Enchantments.BLAST_PROTECTION)<1)s.enchant(Enchantments.BLAST_PROTECTION,1);}@Override public Multimap<Attribute,AttributeModifier> getDefaultAttributeModifiers(EquipmentSlot slot){return slot==EquipmentSlot.CHEST?mods:super.getDefaultAttributeModifiers(slot);}
 @Override public void appendHoverText(ItemStack s,Level l,List<Component> t,TooltipFlag f){t.add(Component.empty());for(int i=1;i<=4;i++)t.add(Component.translatable("item.finalparadox.thorn_knight_aegis.lore."+i));t.add(Component.empty());t.add(Component.translatable("item.finalparadox.legendary"));}
}
